∀ {Observer : Type v} {source target : GRWTSK.ProofHorizon.CorkscrewChamberCap.FiberEndpoint Observer}
  (self : GRWTSK.ProofHorizon.CorkscrewChamberCap.FramedPort source target),
  ∀ x ∈ self.domain, ∀ (i : Observer), |self.residual x i| ≤ self.errorBudget i

∀ {Observer : Type v} {source target : GRWTSK.ProofHorizon.CorkscrewChamberCap.FiberEndpoint Observer}
  {domain : Set source.Carrier} {map : source.Carrier → target.Carrier} {residual : source.Carrier → Observer → ℝ}
  {residual_eq_defect : ∀ x ∈ domain, ∀ (i : Observer), residual x i = target.observe i (map x) - source.observe i x}
  {errorBudget : Observer → ℝ} {errorBudget_nonnegative : ∀ (i : Observer), 0 ≤ errorBudget i}
  {residual_bound : ∀ x ∈ domain, ∀ (i : Observer), |residual x i| ≤ errorBudget i} {domain_1 : Set source.Carrier}
  {map_1 : source.Carrier → target.Carrier} {residual_1 : source.Carrier → Observer → ℝ}
  {residual_eq_defect_1 :
    ∀ x ∈ domain_1, ∀ (i : Observer), residual_1 x i = target.observe i (map_1 x) - source.observe i x}
  {errorBudget_1 : Observer → ℝ} {errorBudget_nonnegative_1 : ∀ (i : Observer), 0 ≤ errorBudget_1 i}
  {residual_bound_1 : ∀ x ∈ domain_1, ∀ (i : Observer), |residual_1 x i| ≤ errorBudget_1 i},
  { domain := domain, map := map, residual := residual, residual_eq_defect := residual_eq_defect,
        errorBudget := errorBudget, errorBudget_nonnegative := errorBudget_nonnegative,
        residual_bound := residual_bound } =
      { domain := domain_1, map := map_1, residual := residual_1, residual_eq_defect := residual_eq_defect_1,
        errorBudget := errorBudget_1, errorBudget_nonnegative := errorBudget_nonnegative_1,
        residual_bound := residual_bound_1 } →
    domain = domain_1 ∧ map = map_1 ∧ residual = residual_1 ∧ errorBudget = errorBudget_1

∀ {Observer : Type v} {A B : GRWTSK.ProofHorizon.CorkscrewChamberCap.FiberEndpoint Observer}
  (P : GRWTSK.ProofHorizon.CorkscrewChamberCap.FramedPort A B),
  ∀ x ∈ P.domain, ∀ (i : Observer), P.residual x i = 0 → B.observe i (P.map x) = A.observe i x

∀ {Observer : Type v} {source target : GRWTSK.ProofHorizon.CorkscrewChamberCap.FiberEndpoint Observer}
  {Discarded : Type w} (self : GRWTSK.ProofHorizon.CorkscrewChamberCap.RankLosingReduction source target Discarded),
  ∃ x y, x ≠ y ∧ self.reduce x = self.reduce y

∀ {Observer : Type v} {source target : GRWTSK.ProofHorizon.CorkscrewChamberCap.FiberEndpoint Observer}
  (self : GRWTSK.ProofHorizon.CorkscrewChamberCap.InvertibleFrameChange source target) (i : Observer)
  (x : source.Carrier), target.observe i (self.equiv x) = source.observe i x

∀ {Observer : Type v} {A B : GRWTSK.ProofHorizon.CorkscrewChamberCap.FiberEndpoint Observer}
  (P : GRWTSK.ProofHorizon.CorkscrewChamberCap.FramedPort A B),
