  {exactKernel : ∀ (ξ : ℝ), angularSpectrum ξ = ∫ (u : ℝ), Complex.exp (-Complex.I * ↑ξ * ↑u) * f u}
  {angularParseval : ‖F‖ ^ 2 = (2 * Real.pi)⁻¹ * ∫ (ξ : ℝ), ‖angularSpectrum ξ‖ ^ 2} {nonnegativeWindow_1 : 0 ≤ T}
  {zeroOutside_1 : ∀ u ∉ Set.Icc 0 T, f u = 0} {integrable_1 : MeasureTheory.Integrable f MeasureTheory.volume}
  {l2Representative_1 : ↑↑F =ᵐ[MeasureTheory.volume] f} {angularSpectrum_1 : ℝ → ℂ}
  {exactKernel_1 : ∀ (ξ : ℝ), angularSpectrum_1 ξ = ∫ (u : ℝ), Complex.exp (-Complex.I * ↑ξ * ↑u) * f u}
  {angularParseval_1 : ‖F‖ ^ 2 = (2 * Real.pi)⁻¹ * ∫ (ξ : ℝ), ‖angularSpectrum_1 ξ‖ ^ 2},
  { nonnegativeWindow := nonnegativeWindow, zeroOutside := zeroOutside, integrable := integrable,
        l2Representative := l2Representative, angularSpectrum := angularSpectrum, exactKernel := exactKernel,
        angularParseval := angularParseval } =
      { nonnegativeWindow := nonnegativeWindow_1, zeroOutside := zeroOutside_1, integrable := integrable_1,
        l2Representative := l2Representative_1, angularSpectrum := angularSpectrum_1, exactKernel := exactKernel_1,
        angularParseval := angularParseval_1 } →
